def create_wings():
    try:
        bpy.ops.mesh.primitive_plane_add(location=(0.0, 0.0, 0.0))
        obj = getattr(bpy.context, "active_object", None)
        if obj:
            obj.name = "spaceship-wings"
            obj.scale = (6.0, 2.5, 0.2)
            try:
                bpy.ops.object.mode_set(mode="EDIT")
                bm = bmesh.from_edit_mesh(obj.data)
                bmesh.ops.extrude_face_region(bm, geom=bm.faces)
                bmesh.ops.translate(bm, verts=[v for v in bm.verts], vec=(0, 0, 0.2))
                bmesh.update_edit_mesh(obj.data)
                bpy.ops.object.mode_set(mode="OBJECT")
            except Exception:
                pass
            if hasattr(obj, "modifiers"):
                mirror = obj.modifiers.new(name="WingMirror", type="MIRROR")
                mirror.use_axis[0] = True
    except Exception:
        pass


