    try:
        positions = [(-4.5, 1.5, 0.0), (-4.5, -1.5, 0.0)]
        for i, pos in enumerate(positions):
            bpy.ops.mesh.primitive_cylinder_add(location=pos)
            obj = getattr(bpy.context, "active_object", None)
            if obj:
                obj.name = f"spaceship-engine-{i + 1}"
