            {"type": "AREA", "location": (-8, 5, 4), "power": 400, "color": (0.6, 0.7, 1.0)},
            {"type": "POINT", "location": (0, 0, 12), "power": 200, "color": (1, 1, 1)},
        ]
        for i, l in enumerate(lights):
            bpy.ops.object.light_add(type=l["type"], location=l["location"])
            light = getattr(bpy.context, "active_object", None)
            if light and hasattr(light, "data"):
                light.name = f"spaceship-light-{i + 1}"
                light.data.energy = l["power"]
                light.data.color = l["color"]
        world = getattr(bpy.context.scene, "world", None)
        if world:
            world.use_nodes = True
            nodes = world.node_tree.nodes
            links = world.node_tree.links
            nodes.clear()
            output = nodes.new(type="ShaderNodeOutputWorld")
            bg = nodes.new(type="ShaderNodeBackground")
            env = nodes.new(type="ShaderNodeTexEnvironment")
            try:
                env.image = bpy.data.images.load("space_environment.exr")
            except Exception:
                pass
            bg.inputs["Strength"].default_value = 0.5
            links.new(env.outputs["Color"], bg.inputs["Color"])
            links.new(bg.outputs["Background"], output.inputs["Surface"])
    except Exception:
        pass


def setup_camera():
    try:
        bpy.ops.object.camera_add(location=(20, -15, 8))
        cam = getattr(bpy.context, "active_object", None)
        if cam:
            cam.name = "spaceship-camera"
            cam.rotation_euler = Euler((math.radians(65), math.radians(0), math.radians(35)), "XYZ")
            if hasattr(cam, "data"):
                cam.data.lens = 85
                if hasattr(cam.data, "dof"):
                    cam.data.dof.use_dof = True
                    cam.data.dof.focus_object = bpy.data.objects.get("spaceship-cockpit")
                    cam.data.dof.aperture_fstop = 2.8
            bpy.context.scene.camera = cam
    except Exception:
        pass


def setup_render():
    try:
        scene = bpy.context.scene
        scene.render.engine = "CYCLES"
        scene.cycles.samples = 1024
        scene.render.resolution_x = 1920
        scene.render.resolution_y = 1080
        scene.render.image_settings.file_format = "PNG"
        if hasattr(scene.cycles, "use_denoising"):
            scene.cycles.use_denoising = True
    except Exception:
        pass


def main():
    clear_scene()
    create_hull()
    create_cockpit()
    create_wings()
    create_engines()
    create_fins()
    create_landing_gear()
    create_materials()
    setup_lighting()
    setup_camera()
    setup_render()


