            do_local_ids=True, do_linked_ids=True, do_recursive=True
        )
    except Exception:
        pass


def _ensure_object_created(obj, name: str):
    if obj is None:
        raise RuntimeError(f"Failed to create {name}")
    return obj


def create_fuselage():
    try:
        bpy.ops.mesh.primitive_cube_add(location=(0, 0, 0))
        obj = _ensure_object_created(getattr(bpy.context, "active_object", None), "fuselage cube")
        obj.name = "fuselage-base"
        obj.scale = (6.0, 1.5, 1.5)
        bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)
        return obj
    except Exception:
        return None


def create_cockpit():
    try:
        bpy.ops.mesh.primitive_uv_sphere_add(
            segments=32, ring_count=16, location=(6.0, 0, 1.0)
        )
        obj = _ensure_object_created(getattr(bpy.context, "active_object", None), "cockpit sphere")
        obj.name = "cockpit-module"
        obj.scale = (1.5, 1.5, 1.0)
        bpy.ops.object.transform_apply(location=False, rotation=False, scale=True)
        return obj
    except Exception:
        return None


