        obj_r.name = "engine-pod-right"
        bpy.ops.mesh.primitive_cylinder_add(
            radius=0.8, depth=4.0, location=(8.0, -1.8, 0.5)
        )
        obj_l = _ensure_object_created(getattr(bpy.context, "active_object", None), "left engine")
        obj_l.name = "engine-pod-left"
        return obj_r, obj_l
    except Exception:
        return None, None


